export const dynamic = "force-static";
// The homepage's "Cinq by text" panel, as carriers and Twilio see the opt-in.
// Recapture it whenever the panel's words change.
const JPEG_BASE64 = "";
export async function GET() {
  const bytes = Buffer.from(JPEG_BASE64, "base64");
  return new Response(bytes, { headers: { "Content-Type": "image/jpeg", "Cache-Control": "public, max-age=3600" } });
}
